\set ON_ERROR_STOP on
BEGIN;
SET LOCAL lock_timeout='3s';
SET LOCAL search_path=pg_catalog,public;
SELECT set_config('srvf.expected_cluster', :'expected_cluster',true);
DO $$BEGIN IF current_database()<>'srvf_staging' OR (SELECT system_identifier::text FROM pg_control_system())<>current_setting('srvf.expected_cluster')
 OR to_regrole('srvf_dp_acceptance_runtime') IS NULL THEN RAISE EXCEPTION 'target mismatch'; END IF; END$$;
LOCK TABLE public."Activity" IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE public."ActivityRuleSnapshot" IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE public."activity_responsibility_assignments" IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE public."notification_outbox_intents" IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE public."role_bindings" IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN
 IF has_table_privilege('srvf_dp_acceptance_runtime','public."Activity"','INSERT') OR ARRAY(SELECT attname::text FROM pg_attribute WHERE attrelid='public."Activity"'::regclass AND attnum>0 AND NOT attisdropped AND has_column_privilege('srvf_dp_acceptance_runtime',attrelid,attnum,'INSERT') ORDER BY attname::text COLLATE "C") <> ARRAY['activityTypeCode','allocationModeCode','archiveWaitingDays','capacity','contributionPolicySelectionRevision','createFromTemplateOperationKey','createFromTemplateRequestHash','createdAt','currentEvidenceRevision','currentPopulationRevision','endAt','galleryAttachmentIds','galleryImageKeys','id','initiatorMemberId','isPublicRegistration','location','metricRequirementCode','metricSelectionRevision','organizationId','requiresInsurance','selectedMetricSetDefinitionHash','selectedMetricSetVersionId','selectedTemplateVersionId','startAt','statusCode','timePolicySelectionRevision','title','updatedAt','workflowRevision']::text[] THEN RAISE EXCEPTION 'baseline mismatch Activity INSERT'; END IF;
 IF (SELECT count(*) FROM pg_attribute a CROSS JOIN LATERAL aclexplode(a.attacl) x WHERE a.attrelid='public."Activity"'::regclass AND a.attname=ANY(ARRAY['activityTypeCode','allocationModeCode','archiveWaitingDays','capacity','contributionPolicySelectionRevision','createFromTemplateOperationKey','createFromTemplateRequestHash','createdAt','currentEvidenceRevision','currentPopulationRevision','endAt','galleryAttachmentIds','galleryImageKeys','id','initiatorMemberId','isPublicRegistration','location','metricRequirementCode','metricSelectionRevision','organizationId','requiresInsurance','selectedMetricSetDefinitionHash','selectedMetricSetVersionId','selectedTemplateVersionId','startAt','statusCode','timePolicySelectionRevision','title','updatedAt','workflowRevision']::text[]) AND x.grantee='srvf_dp_acceptance_runtime'::regrole AND x.grantor=current_user::regrole AND x.privilege_type='INSERT' AND NOT x.is_grantable) <> 30 THEN RAISE EXCEPTION 'grantor mismatch'; END IF;
END $$;
REVOKE INSERT ("activityTypeCode","allocationModeCode","archiveWaitingDays","capacity","contributionPolicySelectionRevision","createFromTemplateOperationKey","createFromTemplateRequestHash","createdAt","currentEvidenceRevision","currentPopulationRevision","endAt","galleryAttachmentIds","galleryImageKeys","id","initiatorMemberId","isPublicRegistration","location","metricRequirementCode","metricSelectionRevision","organizationId","requiresInsurance","selectedMetricSetDefinitionHash","selectedMetricSetVersionId","selectedTemplateVersionId","startAt","statusCode","timePolicySelectionRevision","title","updatedAt","workflowRevision") ON public."Activity" FROM srvf_dp_acceptance_runtime;
DO $$ BEGIN
 IF has_table_privilege('srvf_dp_acceptance_runtime','public."Activity"','UPDATE') OR ARRAY(SELECT attname::text FROM pg_attribute WHERE attrelid='public."Activity"'::regclass AND attnum>0 AND NOT attisdropped AND has_column_privilege('srvf_dp_acceptance_runtime',attrelid,attnum,'UPDATE') ORDER BY attname::text COLLATE "C") <> ARRAY['activityTypeCode','allocationModeCode','archiveWaitingDays','capacity','content','currentPopulationRevision','defaultCheckInRadiusMeters','defaultLocationRequired','description','endAt','genderRequirementCode','id','isPublicRegistration','location','locationLatitude','locationLongitude','organizationId','publishedAt','publishedBy','registrationDeadline','registrationModeCode','registrationNotes','registrationSchema','requiresInsurance','startAt','statusCode','title','updatedAt','visibilityCode','workflowRevision']::text[] THEN RAISE EXCEPTION 'baseline mismatch Activity UPDATE'; END IF;
 IF (SELECT count(*) FROM pg_attribute a CROSS JOIN LATERAL aclexplode(a.attacl) x WHERE a.attrelid='public."Activity"'::regclass AND a.attname=ANY(ARRAY['activityTypeCode','allocationModeCode','archiveWaitingDays','capacity','content','currentPopulationRevision','defaultCheckInRadiusMeters','defaultLocationRequired','description','endAt','genderRequirementCode','isPublicRegistration','location','locationLatitude','locationLongitude','organizationId','publishedAt','publishedBy','registrationDeadline','registrationModeCode','registrationNotes','registrationSchema','requiresInsurance','startAt','statusCode','title','updatedAt','visibilityCode','workflowRevision']::text[]) AND x.grantee='srvf_dp_acceptance_runtime'::regrole AND x.grantor=current_user::regrole AND x.privilege_type='UPDATE' AND NOT x.is_grantable) <> 29 THEN RAISE EXCEPTION 'grantor mismatch'; END IF;
END $$;
REVOKE UPDATE ("activityTypeCode","allocationModeCode","archiveWaitingDays","capacity","content","currentPopulationRevision","defaultCheckInRadiusMeters","defaultLocationRequired","description","endAt","genderRequirementCode","isPublicRegistration","location","locationLatitude","locationLongitude","organizationId","publishedAt","publishedBy","registrationDeadline","registrationModeCode","registrationNotes","registrationSchema","requiresInsurance","startAt","statusCode","title","updatedAt","visibilityCode","workflowRevision") ON public."Activity" FROM srvf_dp_acceptance_runtime;
DO $$ BEGIN
 IF has_table_privilege('srvf_dp_acceptance_runtime','public."ActivityRuleSnapshot"','INSERT') OR ARRAY(SELECT attname::text FROM pg_attribute WHERE attrelid='public."ActivityRuleSnapshot"'::regclass AND attnum>0 AND NOT attisdropped AND has_column_privilege('srvf_dp_acceptance_runtime',attrelid,attnum,'INSERT') ORDER BY attname::text COLLATE "C") <> ARRAY['activityId','contributionPolicySelectionRevisionId','createdAt','createdByReviewId','id','resolvedConfig','snapshotHash','templateVersionId','timePolicySelectionRevisionId','workflowRevision']::text[] THEN RAISE EXCEPTION 'baseline mismatch ActivityRuleSnapshot INSERT'; END IF;
 IF (SELECT count(*) FROM pg_attribute a CROSS JOIN LATERAL aclexplode(a.attacl) x WHERE a.attrelid='public."ActivityRuleSnapshot"'::regclass AND a.attname=ANY(ARRAY['activityId','contributionPolicySelectionRevisionId','createdAt','createdByReviewId','id','resolvedConfig','snapshotHash','templateVersionId','timePolicySelectionRevisionId','workflowRevision']::text[]) AND x.grantee='srvf_dp_acceptance_runtime'::regrole AND x.grantor=current_user::regrole AND x.privilege_type='INSERT' AND NOT x.is_grantable) <> 10 THEN RAISE EXCEPTION 'grantor mismatch'; END IF;
END $$;
REVOKE INSERT ("activityId","contributionPolicySelectionRevisionId","createdAt","createdByReviewId","id","resolvedConfig","snapshotHash","templateVersionId","timePolicySelectionRevisionId","workflowRevision") ON public."ActivityRuleSnapshot" FROM srvf_dp_acceptance_runtime;
DO $$ BEGIN
 IF has_table_privilege('srvf_dp_acceptance_runtime','public."ActivityRuleSnapshot"','SELECT') OR ARRAY(SELECT attname::text FROM pg_attribute WHERE attrelid='public."ActivityRuleSnapshot"'::regclass AND attnum>0 AND NOT attisdropped AND has_column_privilege('srvf_dp_acceptance_runtime',attrelid,attnum,'SELECT') ORDER BY attname::text COLLATE "C") <> ARRAY['activityId','contributionPolicySelectionRevisionId','createdAt','createdByReviewId','id','resolvedConfig','snapshotHash','templateVersionId','timePolicySelectionRevisionId','workflowRevision']::text[] THEN RAISE EXCEPTION 'baseline mismatch ActivityRuleSnapshot SELECT'; END IF;
 IF (SELECT count(*) FROM pg_attribute a CROSS JOIN LATERAL aclexplode(a.attacl) x WHERE a.attrelid='public."ActivityRuleSnapshot"'::regclass AND a.attname=ANY(ARRAY['activityId','contributionPolicySelectionRevisionId','createdAt','createdByReviewId','id','resolvedConfig','snapshotHash','templateVersionId','timePolicySelectionRevisionId','workflowRevision']::text[]) AND x.grantee='srvf_dp_acceptance_runtime'::regrole AND x.grantor=current_user::regrole AND x.privilege_type='SELECT' AND NOT x.is_grantable) <> 10 THEN RAISE EXCEPTION 'grantor mismatch'; END IF;
END $$;
REVOKE SELECT ("activityId","contributionPolicySelectionRevisionId","createdAt","createdByReviewId","id","resolvedConfig","snapshotHash","templateVersionId","timePolicySelectionRevisionId","workflowRevision") ON public."ActivityRuleSnapshot" FROM srvf_dp_acceptance_runtime;
DO $$ BEGIN
 IF has_table_privilege('srvf_dp_acceptance_runtime','public."activity_responsibility_assignments"','INSERT') OR ARRAY(SELECT attname::text FROM pg_attribute WHERE attrelid='public."activity_responsibility_assignments"'::regclass AND attnum>0 AND NOT attisdropped AND has_column_privilege('srvf_dp_acceptance_runtime',attrelid,attnum,'INSERT') ORDER BY attname::text COLLATE "C") <> ARRAY['activityId','assignedByUserId','canManageAttendance','canManageRegistrations','createdAt','id','memberId','responsibilityType','source','startedAt','status','updatedAt']::text[] THEN RAISE EXCEPTION 'baseline mismatch activity_responsibility_assignments INSERT'; END IF;
 IF (SELECT count(*) FROM pg_attribute a CROSS JOIN LATERAL aclexplode(a.attacl) x WHERE a.attrelid='public."activity_responsibility_assignments"'::regclass AND a.attname=ANY(ARRAY['activityId','assignedByUserId','canManageAttendance','canManageRegistrations','createdAt','id','memberId','responsibilityType','source','startedAt','status','updatedAt']::text[]) AND x.grantee='srvf_dp_acceptance_runtime'::regrole AND x.grantor=current_user::regrole AND x.privilege_type='INSERT' AND NOT x.is_grantable) <> 12 THEN RAISE EXCEPTION 'grantor mismatch'; END IF;
END $$;
REVOKE INSERT ("activityId","assignedByUserId","canManageAttendance","canManageRegistrations","createdAt","id","memberId","responsibilityType","source","startedAt","status","updatedAt") ON public."activity_responsibility_assignments" FROM srvf_dp_acceptance_runtime;
DO $$ BEGIN
 IF has_table_privilege('srvf_dp_acceptance_runtime','public."activity_responsibility_assignments"','SELECT') OR ARRAY(SELECT attname::text FROM pg_attribute WHERE attrelid='public."activity_responsibility_assignments"'::regclass AND attnum>0 AND NOT attisdropped AND has_column_privilege('srvf_dp_acceptance_runtime',attrelid,attnum,'SELECT') ORDER BY attname::text COLLATE "C") <> ARRAY['activityId','assignedByUserId','canManageAttendance','canManageRegistrations','endedAt','endedByUserId','id','memberId','reason','responsibilityType','source','startedAt','status']::text[] THEN RAISE EXCEPTION 'baseline mismatch activity_responsibility_assignments SELECT'; END IF;
 IF (SELECT count(*) FROM pg_attribute a CROSS JOIN LATERAL aclexplode(a.attacl) x WHERE a.attrelid='public."activity_responsibility_assignments"'::regclass AND a.attname=ANY(ARRAY['activityId','assignedByUserId','canManageAttendance','canManageRegistrations','endedAt','endedByUserId','id','memberId','reason','responsibilityType','source','startedAt','status']::text[]) AND x.grantee='srvf_dp_acceptance_runtime'::regrole AND x.grantor=current_user::regrole AND x.privilege_type='SELECT' AND NOT x.is_grantable) <> 13 THEN RAISE EXCEPTION 'grantor mismatch'; END IF;
END $$;
REVOKE SELECT ("activityId","assignedByUserId","canManageAttendance","canManageRegistrations","endedAt","endedByUserId","id","memberId","reason","responsibilityType","source","startedAt","status") ON public."activity_responsibility_assignments" FROM srvf_dp_acceptance_runtime;
DO $$ BEGIN
 IF has_table_privilege('srvf_dp_acceptance_runtime','public."notification_outbox_intents"','INSERT') OR ARRAY(SELECT attname::text FROM pg_attribute WHERE attrelid='public."notification_outbox_intents"'::regclass AND attnum>0 AND NOT attisdropped AND has_column_privilege('srvf_dp_acceptance_runtime',attrelid,attnum,'INSERT') ORDER BY attname::text COLLATE "C") <> ARRAY['aggregateId','aggregateType','attempts','availableAt','createdAt','destinationRef','destinationType','eventKey','eventType','id','payload','payloadVersion','status','updatedAt']::text[] THEN RAISE EXCEPTION 'baseline mismatch notification_outbox_intents INSERT'; END IF;
 IF (SELECT count(*) FROM pg_attribute a CROSS JOIN LATERAL aclexplode(a.attacl) x WHERE a.attrelid='public."notification_outbox_intents"'::regclass AND a.attname=ANY(ARRAY['aggregateId','aggregateType','attempts','availableAt','createdAt','destinationRef','destinationType','eventKey','eventType','id','payload','payloadVersion','status','updatedAt']::text[]) AND x.grantee='srvf_dp_acceptance_runtime'::regrole AND x.grantor=current_user::regrole AND x.privilege_type='INSERT' AND NOT x.is_grantable) <> 14 THEN RAISE EXCEPTION 'grantor mismatch'; END IF;
END $$;
REVOKE INSERT ("aggregateId","aggregateType","attempts","availableAt","createdAt","destinationRef","destinationType","eventKey","eventType","id","payload","payloadVersion","status","updatedAt") ON public."notification_outbox_intents" FROM srvf_dp_acceptance_runtime;
DO $$ BEGIN
 IF has_table_privilege('srvf_dp_acceptance_runtime','public."role_bindings"','INSERT') OR ARRAY(SELECT attname::text FROM pg_attribute WHERE attrelid='public."role_bindings"'::regclass AND attnum>0 AND NOT attisdropped AND has_column_privilege('srvf_dp_acceptance_runtime',attrelid,attnum,'INSERT') ORDER BY attname::text COLLATE "C") <> ARRAY['createdAt','createdByUserId','id','note','principalId','principalType','roleId','scopeActivityId','scopeType','startedAt','status','updatedAt']::text[] THEN RAISE EXCEPTION 'baseline mismatch role_bindings INSERT'; END IF;
 IF (SELECT count(*) FROM pg_attribute a CROSS JOIN LATERAL aclexplode(a.attacl) x WHERE a.attrelid='public."role_bindings"'::regclass AND a.attname=ANY(ARRAY['createdAt','createdByUserId','id','note','principalId','principalType','roleId','scopeActivityId','scopeType','startedAt','status','updatedAt']::text[]) AND x.grantee='srvf_dp_acceptance_runtime'::regrole AND x.grantor=current_user::regrole AND x.privilege_type='INSERT' AND NOT x.is_grantable) <> 12 THEN RAISE EXCEPTION 'grantor mismatch'; END IF;
END $$;
REVOKE INSERT ("createdAt","createdByUserId","id","note","principalId","principalType","roleId","scopeActivityId","scopeType","startedAt","status","updatedAt") ON public."role_bindings" FROM srvf_dp_acceptance_runtime;
COMMIT;
